#pragma once

#include <cstdint>

namespace inapparency::display {

// 1-bit picture, rows top to bottom, each row padded to whole bytes, most
// significant bit is the leftmost pixel.
struct Bitmap {
    int width;
    int height;
    const std::uint8_t* data;

    bool get(int x, int y) const {
        if (x < 0 || y < 0 || x >= width || y >= height) {
            return false;
        }
        const int stride = (width + 7) / 8;
        return (data[y * stride + x / 8] & (0x80 >> (x % 8))) != 0;
    }
};

// The project logo (a protogen), generated by tools/make_logo.py.
extern const Bitmap kLogoBitmap;

} // namespace inapparency::display
